const toggle=document.getElementById('theme-toggle');function sync(){const dark=document.documentElement.dataset.theme==='dark';toggle.innerHTML=dark?'☀ <span>Light mode</span>':'☾ <span>Dark mode</span>';toggle.setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode')}toggle.onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('sonic-theme',document.documentElement.dataset.theme)}catch{}sync()};sync();const form=document.getElementById('contact-form');if(form)form.onsubmit=async event=>{event.preventDefault();if(form.getAttribute('aria-busy')==='true')return;if(!document.getElementById('contact-message').value.trim()){document.getElementById('contact-status').textContent='Please enter a message.';return}const button=form.querySelector('button[type="submit"]'),status=document.getElementById('contact-status');button.disabled=true;form.setAttribute('aria-busy','true');window.SonicActivity?.start('contact');button.textContent='Sending…';status.textContent='';try{const response=await fetch(form.action,{method:'POST',headers:{Accept:'application/json'},body:new FormData(form)});let data={};try{data=await response.json()}catch{}if(!response.ok)throw Error(data.errors?.map(e=>e.message).join(' ')||'Your message could not be sent. Please try again.');status.textContent='Your message has been submitted. Thank you for getting in touch.';window.SonicActivity?.finish(true,status.textContent);form.reset()}catch(error){status.textContent=error.message==='Failed to fetch'?'Unable to connect. Check your connection and try again.':error.message||'Your message could not be sent.';window.SonicActivity?.finish(false,status.textContent)}finally{form.removeAttribute('aria-busy');button.disabled=false;button.textContent='Send message'}};